import pandas as pd


def clean(df):
    df = df.copy()
    # flipper_length_mm is stored as text (e.g. "180"); convert to numeric
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    # remove exact duplicate rows (2 present) so averages aren't skewed
    df = df.drop_duplicates()
    return df


def answer(df):
    df = clean(df)
    result = {}
    grouped = df.groupby('species')['flipper_length_mm'].mean()
    for species, val in grouped.items():
        if pd.notna(val):
            result[species] = float(val)
    return result
